package com.memobell.app;
import android.app.*;import android.content.*;import org.json.*;
public class BootReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent in){if(!Intent.ACTION_BOOT_COMPLETED.equals(in.getAction()))return;try{JSONArray a=new JSONArray(c.getSharedPreferences("memobell_data",0).getString("notes","[]"));for(int x=0;x<a.length();x++){JSONObject n=a.optJSONObject(x);if(n==null)continue;long w=n.optLong("when");if(w<=System.currentTimeMillis())continue;int id=n.optInt("id");Intent i=new Intent(c,ReminderReceiver.class);i.putExtra("id",id);i.putExtra("text",n.optString("text"));i.putExtra("daily",n.optBoolean("daily"));PendingIntent pi=PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,w,pi);}}catch(Exception ignored){}} }
